const $=s=>document.querySelector(s);const photo=(id,w=700)=>`assets/${id}.jpg`;
const categories=[['Nannies','♡','Care for your little ones'],['Cleaning','✧','A fresh start for your space'],['Mechanics','⚒','Keep your world moving'],['Hair & beauty','✂','Look good. Feel great.'],['Skilled hands','⌂','The right hands for the job']];
const profiles=[];
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};const persist=(key,val)=>{try{localStorage.setItem(key,JSON.stringify(val))}catch{toast('Your browser could not save this change.')}};let saved=read('fyield-saved',[]);saved=Array.isArray(saved)?saved.filter(id=>Number.isInteger(id)||typeof id==='string').slice(0,200):[];let drafts=[],selected='All services',savedOnly=false;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function openModal(html){$('#modal').classList.remove('wide');$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function choose(cat){selected=cat;savedOnly=false;$('#query').value='';render();$('#providers').scrollIntoView({behavior:'smooth',block:'center'})}
function render(){const items=[...drafts,...profiles];$('#savedCount').textContent=saved.length;$('#savedBtn').setAttribute('aria-pressed',savedOnly);$('#categories').innerHTML=categories.map(([cat,icon,desc])=>`<button class="cat ${selected===cat?'selected':''}" data-cat="${cat}" aria-pressed="${selected===cat}"><span class="cat-icon" aria-hidden="true">${icon}</span><h3>${cat}<span>↗</span></h3><p>${desc}</p></button>`).join('');$('#chips').innerHTML=['All services',...categories.map(c=>c[0])].map(c=>`<button class="chip ${c===selected?'selected':''}" data-cat="${c}" aria-pressed="${c===selected}">${c}</button>`).join('');const q=$('#query').value.toLowerCase().trim(),loc=$('#location').value;let shown=items.filter(p=>(selected==='All services'||p.category===selected)&&(!savedOnly||saved.includes(p.id))&&(!loc||p.area===loc)&&(!q||[p.name,p.category,p.title,p.location,p.area,...p.skills].join(' ').toLowerCase().includes(q)));if($('#sort').value==='low')shown.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')shown.sort((a,b)=>b.price-a.price);$('#resultsTitle').textContent=savedOnly?'Your saved professionals.':selected!=='All services'?`${selected}, with a human touch.`:'Good people. Ready to help.';$('#providers').innerHTML=shown.map(p=>`<article class="provider"><div class="card-img"><img src="${esc(p.photos?.[0]?.url||(p.image?photo(p.image):'assets/fyield-logo.jpeg'))}" alt="${esc(p.category)} service illustration" loading="lazy"><button class="save ${saved.includes(p.id)?'is-saved':''}" data-save="${esc(p.id)}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button><span class="card-type">${esc(p.category)}${typeof p.id==='number'?' · Example':''}</span></div><div class="card-body"><button class="provider-title" data-profile="${esc(p.id)}">${esc(p.name)} ↗</button><p>${esc(p.title)}</p><div class="card-meta">⌖ ${esc(p.area)}, Abuja</div><div class="card-rating">${p.reviewCount?`★ ${p.rating} · ${p.reviewCount} reviews`:'☆ No reviews yet'}</div><div class="card-bottom"><span>From <b>₦${Number(p.price).toLocaleString()}</b> / ${esc(p.unit)}</span><button class="arrow" data-profile="${esc(p.id)}" aria-label="View ${esc(p.name)}">↗</button></div></div></article>`).join('');$('#empty').hidden=shown.length>0;$('#empty').innerHTML=items.length?'No matching services yet. Try another category or location.':'<strong>Abuja, let’s put your skills on the map.</strong><span>We’re welcoming our first service providers. Create your profile and help customers discover your work.</span><button class="btn dark" id="joinCommunity">Offer a service ↗</button>';if($('#joinCommunity'))$('#joinCommunity').onclick=listing;$('#reset').hidden=!items.length;$('#resultsTitle').textContent=items.length?$('#resultsTitle').textContent:'Your next opportunity starts here.';document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>choose(b.dataset.cat));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=/^\d+$/.test(b.dataset.save)?Number(b.dataset.save):b.dataset.save;saved=saved.includes(id)?saved.filter(i=>i!==id):[...saved,id];persist('fyield-saved',saved);render()});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>profile(/^\d+$/.test(b.dataset.profile)?Number(b.dataset.profile):b.dataset.profile))}
function profile(id){details(id)}
function enquiry(p){openModal(`<div class="eyebrow">ABUJA LAUNCH PREVIEW</div><h2>Real connections, coming next.</h2><p>${esc(p.name)} is an illustrative profile. Enquiries and bookings are not available in this preview.</p><p class="notice">We are not collecting names, addresses, phone numbers, childcare information, or job descriptions here. Provider contact will open after accounts and protected messaging are ready.</p><button class="btn dark" id="done">Keep exploring →</button>`);$('#done').onclick=()=>$('#modal').close()}
function listing(){editProvider()}
function privacy(){openModal(`<div class="eyebrow">CLEAR FROM THE START</div><h2>Your data on Fyield.</h2><p>Providers can now publish profiles and work photos. Enquiries do not confirm a booking.</p><h3>What stays on your device</h3><p>Saved favorites contain only profile IDs. Search and filters remain in the page. Account details and private enquiries are stored on the server behind authenticated access controls. Passwords are hashed by our authentication service. Public profiles, photos, and reviews are visible to visitors. Do not upload identity documents, payment information, or children’s details.</p><h3>Hosting and imagery</h3><p>Hosting providers may process ordinary connection information such as IP addresses to deliver the site. Images are stored with Vercel Blob; accounts, profiles, reviews, and enquiries use Neon Postgres. When email verification is enabled, our email delivery provider processes your email address to deliver sign-in codes. Approved administrators can view account contact details, provider listings and reviews to operate Fyield; the admin dashboard does not expose private enquiry content. This version includes no analytics or advertising trackers.</p><h3>Manage your information</h3><p>You can edit or remove your public profile, remove your own reviews, and change your password from your account. Provider removal also removes its reviews and enquiries. Account deletion and email recovery are not yet self-service.</p><h3>Earlier prototype drafts</h3><p>If you used an earlier preview on this same address, you can remove its saved enquiries, listings, and favorites below. Data on another address or file must be cleared there.</p><button class="btn outline" id="clearData">Clear this preview’s saved data</button>`);$('#clearData').onclick=()=>{try{['fyield-saved','fyield-listings','fyield-enquiries'].forEach(k=>localStorage.removeItem(k));saved=[];render();toast('Preview data cleared from this address.')}catch{toast('Storage is unavailable. Clear site data in your browser settings.')}}}
$('#privacyBtn').onclick=privacy;
$('#searchForm').onsubmit=e=>{e.preventDefault();selected='All services';savedOnly=false;render();$('#providers').scrollIntoView({behavior:'smooth',block:'start'})};$('#sort').onchange=render;$('#location').onchange=render;$('#savedBtn').onclick=()=>{savedOnly=!savedOnly;selected='All services';$('#query').value='';$('#location').value='';render();$('#providers').scrollIntoView({behavior:'smooth'})};function reset(){selected='All services';savedOnly=false;$('#query').value='';$('#location').value='';render();$('#providers').scrollIntoView({behavior:'smooth',block:'center'})}$('#reset').onclick=reset;$('#allServices').onclick=reset;document.querySelectorAll('[data-list]').forEach(b=>b.onclick=listing);document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{selected='All services';savedOnly=false;$('#query').value=b.dataset.query;render();$('#providers').scrollIntoView({behavior:'smooth'})});render();
